def rules(folder,name,x):
    n=name.lower();dur=x['duration_s']
    if folder=='Sanspes':
        sud='sudden' in n
        return S(F_RISE,"Short suspense sting with a sudden "+("jolt" if sud else "tension swell"),['jumpscare','suspense','shock'] if sud else ['suspense','near_death','reveal'],['riser','stinger'] if sud else ['riser','ambience'],'tense',4 if sud else 3,['suspense','tension','sting'])
    if folder=='Anime SFX':
        key=next((k for k in ANIME if k in n),None)
        f,m,r,mood,e,t=ANIME[key] if key else (F_TOON,['punchline','fail','emphasis'],['hit'],'comedic',3,['anime'])
        return S(f,f"Anime/cartoon gag sound effect: {name.rsplit('.',1)[0]}",m,r,mood,e,t,copyright='medium' if key=='pokemon' else 'low')
    if folder=='Approach':
        if 'hissing' in n: return S(F_RISE,"Hissing approach riser that swells toward an impact",['suspense','reveal','hook'],['riser'],'building',3,['approach','riser','hiss','build up'])
        if 'swooshy' in n: return S(F_RISE,"Swooshy approach riser building toward a hit",['suspense','speed','reveal'],['riser','whoosh'],'building',3,['approach','swoosh','riser'])
        if 'sci-fi' in n: return S(F_RISE,"Sci-fi approach riser with synthetic sweep",['suspense','tech_glitch','reveal'],['riser'],'building',3,['approach','sci-fi','riser'])
        if 'whistling' in n: return S(F_RISE,"Whistling approach rising tone",['suspense','speed','jumpscare'],['riser'],'building',3,['approach','whistle','riser'])
        if 'rumbling' in n: return S(F_RISE,"Rumbling bass approach riser",['suspense','explosion','reveal'],['riser'],'ominous',4,['approach','rumble','riser'])
        if 'blockbuster' in n: return S(F_RISE,"Tense evolving blockbuster approach riser",['suspense','reveal','victory'],['riser'],'epic',4,['approach','blockbuster','cinematic','riser'])
        if 'bass' in n: return S(F_RISE,"Bass approach riser leading into a drop",['suspense','reveal','emphasis'],['riser'],'building',4,['approach','bass','riser'])
        if 'epic' in n: return S(F_RISE,"Epic cinematic approach riser",['suspense','reveal','intro'],['riser'],'epic',4,['approach','epic','cinematic','riser'])
        return S(F_RISE,"Dramatic approach riser",['suspense','reveal','hook'],['riser'],'dramatic',3,['approach','dramatic','riser'])
    if folder=='Bass':
        if 'approach' in n: return S(F_RISE,"Riser that approaches into a bass drop",['suspense','reveal','emphasis'],['riser','hit'],'building',4,['bass drop','riser','approach'])
        if 'bend' in n: return S(F_HIT,"Clean bass bend (pitch-sliding sub bass)",['emphasis','slow_mo','shock'],['hit'],'heavy',3,['bass','bend','sub'])
        if 'soft' in n: return S(F_HIT,"Soft clean bass thump",['emphasis','suspense'],['hit'],'heavy',2,['bass','soft','sub'])
        return S(F_HIT,"Bass drop impact"+(" with noisy/distorted texture" if 'noisy' in n or 'dist' in n else ""),['emphasis','punchline','reveal','explosion'],['hit'],'heavy',4,['bass drop','impact','sub'])
    if folder=='Beep':
        t=['beep','ui','tech']
        if 'arpeggiated' in n: return S(F_UI,"Arpeggiated UI beep run",['small_win','progress','tech_glitch'],['ui_sound'],'techy',2,t+['arpeggio'])
        if 'multiple' in n: return S(F_UI,"Multiple rapid UI beeps",['progress','tech_glitch','small_win'],['ui_sound'],'techy',2,t+['multiple'])
        if 'double' in n: return S(F_UI,"UI double beep",['small_win','emphasis','progress'],['ui_sound'],'neutral',2,t+['double'])
        if 'evolving' in n: return S(F_UI,"Evolving sci-fi beep sequence",['tech_glitch','reveal','progress'],['ui_sound'],'techy',2,t+['sci-fi'])
        if 'echo' in n: return S(F_UI,"Echoing beep",['tech_glitch','suspense','small_win'],['ui_sound'],'techy',2,t+['echo'])
        return S(F_UI,"Single short UI beep",['small_win','emphasis','progress'],['ui_sound'],'neutral',1,t)
    if folder=='Blab': return S(F_UI,"Short synthetic UI blab / chatter blip",['emphasis','small_win','awkward'],['ui_sound'],'quirky',1,['blab','ui','chatter'])
    if folder=='Blast':
        k='energy gun' if 'energy' in n else 'laser gun' if 'laser' in n else 'pulse gun' if 'pulse' in n else 'teleport'
        m=['combat','explosion','emphasis'] if k!='teleport' else ['scene_change','speed','tech_glitch']
        return S(F_GLITCH,f"Sci-fi {k} blast",m,['hit','literal'] if k!='teleport' else ['whoosh','literal'],'action',4,['sci-fi','blast',k,'laser'])
    if folder=='Bleep': return S(F_UI,"Short censor-style bleep tone",['censor','rage','punchline'],['ui_sound','literal'],'censor',2,['bleep','censor','swear cover'])
    if folder=='Blip': return S(F_UI,"Short blip pop"+(" made with the mouth" if 'mouth' in n else " (synthetic)"),['emphasis','small_win','awkward'],['ui_sound'],'playful',1,['blip','pop'])
    if folder=='Blow':
        if 'balloon' in n: return S(F_FOLEY,"Blowing up a balloon",['building','awkward','punchline'],['literal'],'silly',2,['balloon','blow','inflate'])
        if 'synthetic' in n: return S(F_WHOOSH,"Synthetic air blow swish",['scene_change','speed','emphasis'],['whoosh'],'airy',2,['blow','air','synthetic','swish'])
        return S(F_FOLEY,"Blowing air with the mouth",['awkward','eat_drink','punchline'],['literal'],'airy',1,['blow','mouth','breath'])
    if folder=='Book': return S(F_FOLEY,"Heavy book dropped on a surface with room tail",['emphasis','fail','awkward'],['hit','literal'],'dull',2,['book','drop','thud'])
    if folder.startswith('Boom'):
        lvl=folder.split('/')[1]
        if 'horror' in n: return S(F_HIT,"Strong horror cinematic boom with eerie tail",['jumpscare','shock','reveal'],['hit'],'scary',5,['boom','horror','cinematic'],vol=-4)
        if 'sci-fi' in n: return S(F_HIT,f"{lvl} sci-fi boom impact",['reveal','shock','emphasis'],['hit'],'techy',4 if lvl!='Soft' else 3,['boom','sci-fi','impact'],vol=-3 if lvl=='Strong' else 0)
        e={'Soft':2,'Medium':3,'Strong':5}[lvl]
        mm={'Soft':['emphasis','reveal','suspense'],'Medium':['emphasis','shock','reveal','punchline'],'Strong':['explosion','shock','victory','reveal','punchline']}[lvl]
        k='blockbuster hit' if 'blockbuster' in n else 'epic boom' if 'epic' in n else 'cinematic boom'
        return S(F_HIT,f"{lvl} {k} with long decaying tail",mm,['hit'],'epic' if lvl!='Soft' else 'dramatic',e,['boom','cinematic','impact',lvl.lower(),'bass drop'],vol={'Soft':3,'Medium':0,'Strong':-4}[lvl])
    if folder=='Buzz':
        k=('robotic arm' if 'robotic arm' in n else 'rotary robotic' if 'rotary' in n else 'grinding' if 'grinding' in n else 'machine' if 'machine' in n else 'sci-fi')
        return S(F_GLITCH,f"{k.title()} buzz",['tech_glitch','building','suspense'],['literal'],'mechanical',2,['buzz',k,'machine','sci-fi'])
    if folder=='Clang':
        if 'wine' in n: return S(F_UI,"Wineglass clang / ting",['small_win','emphasis','money'],['ui_sound','hit'],'bright',2,['wineglass','clang','glass','ting'])
        return S(F_HIT,"Synthetic metallic clang",['emphasis','combat','fail'],['hit'],'metallic',3,['clang','metal','synthetic'])
    if folder=='Click':
        if 'keyboard' in n: return S(F_UI,"Mechanical keyboard "+("multi-key clicks" if 'multiple' in n else "key click"),['building','tech_glitch','progress'],['ui_sound','literal'],'techy',1,['keyboard','typing','click'])
        if 'camera' in n: return S(F_UI,"Camera "+("roll" if 'roll' in n else "shutter")+" click",['reveal','emphasis','flex'],['ui_sound','literal'],'neutral',2,['camera','shutter','photo'])
        if 'lighter' in n: return S(F_UI,"Lighter double click",['emphasis','suspense','small_win'],['ui_sound','literal'],'neutral',1,['lighter','click'])
        if 'pen' in n: return S(F_UI,"Pen click",['small_win','emphasis','progress'],['ui_sound'],'neutral',1,['pen','click'])
        if 'mouse' in n: return S(F_UI,"Computer mouse click",['progress','tech_glitch','emphasis'],['ui_sound'],'neutral',1,['mouse','click'])
        return S(F_UI,"Soft UI click",['emphasis','progress','small_win'],['ui_sound'],'neutral',1,['click','soft'])
    if folder=='Click/BeatBox': return S(F_UI,"Beatbox-style mouth click",['emphasis','punchline','awkward'],['ui_sound'],'playful',2,['beatbox','click','mouth'])
    if folder=='Click/Digital': return S(F_UI,"Digital UI click",['progress','tech_glitch','small_win'],['ui_sound'],'techy',1,['digital','click','ui'])
    if folder=='Click/Mouse': return S(F_UI,"Computer mouse click",['progress','tech_glitch','emphasis'],['ui_sound'],'neutral',1,['mouse','click'])
    if folder=='Click/Pop':
        if n.startswith('clop'): return S(F_UI,"Wooden 'clop' pop with tail",['emphasis','punchline','awkward'],['ui_sound','hit'],'playful',2,['clop','pop','wood'])
        return S(F_UI,"Bubble pop",['emphasis','punchline','small_win'],['ui_sound','hit'],'playful',2,['pop','bubble'])
    if folder=='Clink':
        if 'glittering' in n: return S(F_UI,"Glittering magical clink / chime",['loot','small_win','reveal'],['ui_sound'],'magical',2,['glitter','chime','sparkle','clink'])
        if 'shake' in n: return S(F_UI,"Coins shaking and clinking",['money','loot','small_win'],['ui_sound','literal'],'rich',2,['coins','shake','money'])
        return S(F_UI,"Single coin drop clink",['money','loot','small_win'],['ui_sound','literal'],'rich',2,['coin','clink','money'])
    if folder=='Clock': return S(F_FOLEY,"Clock ticking",['time_skip','suspense','awkward'],['ambience','literal'],'tense',2,['clock','ticking','time'])
    if folder=='Crack':
        bite='bite' in n
        k=next(k for k in ['apple','cracker','rubbery plastic','plastic','small dry','wood'] if k in n)
        return S(F_FOLEY,f"{k.title()} crackle"+(" (bite)" if bite else ""),['eat_drink','emphasis','building'] if bite else ['building','emphasis','fail'],['literal'],'crunchy',2,[k,'crackle','crunch']+(['bite','eating'] if bite else []))
    if folder=='Creak':
        ru='rubber' in n
        return S(F_TOON if ru else F_FOLEY,"Rubber creak squeak" if ru else "Clean creaky squeak",['awkward','suspense','punchline'],['literal','reaction'],'awkward',2,['creak','squeak','rubber' if ru else 'wood'])
    if folder=='Crumple': return S(F_FOLEY,"Short dry paper crumple",['building','awkward','fail'],['literal'],'neutral',1,['paper','crumple'])
    if folder=='Cyber': return S(F_GLITCH,"Cyber data stream / digital processing texture",['tech_glitch','reveal','suspense'],['ambience'],'techy',3,['cyber','data','digital','sci-fi'])
    if folder=='Doink':
        k='deep' if 'deep' in n else 'synthetic' if 'synth' in n else 'acoustic'
        return S(F_TOON,f"{k.title()} doink boing",['fail','punchline','emphasis'],['hit','reaction'],'comedic',2,['doink','boing',k,'cartoon'])
    if folder=='Drone':
        return S(F_RISE,"Sci-fi drone "+("that accelerates" if 'accel' in n else "that decelerates" if 'decel' in n else "that evolves"),['suspense','tech_glitch','slow_mo','reveal'],['ambience','riser'],'eerie',3,['drone','sci-fi','tension'])
    if folder=='Fall': return S(F_STING,"Sad 'wha wha' fail trombone jingle",['fail','sad','irony'],['stinger'],'comedic',2,['fail','wha wha','sad trombone'],frequency='signature')
    if folder=='Glitch' or folder.startswith('Glitch/'):
        sub=folder.split('/')[1] if '/' in folder else 'plain'
        d={'Beep':"Beeping digital glitch",'Blast':"Short glitchy blast",'Buzzing':"Buzzing power glitch",'Crackle':"Crackling glitch",'Flapping':"Digital flapping glitch",
           'Hiss':"Glitchy hiss",'Miscellaneous':"Miscellaneous glitch",'Rattle':"Clicking mechanical rattle glitch",'Rustle':"Digital rustle glitch",'Squeaky':"Squeaky glitch",'plain':"Digital glitch"}[sub]
        m=['tech_glitch','shock','scene_change'] if dur<3 else ['tech_glitch','suspense','scene_change']
        if sub=='Hiss' and dur>10: return S(F_GLITCH,"Very long soft glitchy hiss bed",['tech_glitch','suspense'],['ambience'],'eerie',2,['glitch','hiss','ambience','long'],notes='Very long file; trim a section')
        if 'slow-down' in n: d="Malfunctioning slow-down (tape/power-down glitch)"; m=['tech_glitch','fail','slow_mo']
        e=3 if dur<1.5 else 4 if sub in('Blast','Buzzing') else 3
        return S(F_GLITCH,d,m,['literal','transition'] if dur>=0.5 else ['hit','literal'],'glitchy',e,['glitch','digital','tech error']+([sub.lower()] if sub!='plain' else []))
    if folder=='Hiss':
        if 'spray' in n: return S(F_FOLEY,"Short spray hiss",['emphasis','scene_change','fail'],['literal'],'neutral',1,['spray','hiss','aerosol'])
        return S(F_GLITCH,("Digital hiss texture" if 'digital' in n else "Sci-fi mechanical hiss (steam/pneumatic)"),['tech_glitch','reveal','scene_change'],['literal','ambience'],'techy',2,['hiss','sci-fi'])
    if folder=='Hit':
        if 'kick' in n: return S(F_HIT,"Punchy kick impact",['combat','fail','emphasis'],['hit','literal'],'physical',3,['kick','impact','fight'])
        return S(F_HIT,"Punch impact",['combat','fail','emphasis'],['hit','literal'],'physical',3,['punch','impact','fight'])
    if folder=='Keyboard': return S(F_UI,"Long keyboard typing recording (~30s)",['building','tech_glitch','progress'],['ambience','literal'],'busy',1,['keyboard','typing','hacking'],notes='~30s continuous typing; use a sub-range')
    if folder=='More Sounds': return MORE[n.rsplit('.',1)[0]]
    raise Exception(folder+name)

CLEAN_PFX={'Click/BeatBox':'BeatBox Click','Click/Digital':'Digital Click','Click/Mouse':'Mouse Click','Keyboard':'Keyboard Typing','Clock':'Clock Ticking','Book':'Book Drop','Cyber':'Cyber Data'}
out=[]
for x in batch:
    p=x['path'].split('SFX (2)/SFX (2)/')[-1]
    folder,base=p.rsplit('/',1)
    folder=folder.strip()
    base_ns=base.rsplit('.',1)[0]
    sp=rules(folder,base,x)
    a=x.get('audio') or {}
    loud=a.get('loud_db',-20)
    vol=sp.get('vol')
    if vol is None: vol=-4 if loud>-9 else -2 if loud>-13 else 3 if loud<-30 else 0
    clean=sp.get('clean')
    nm=num(base)
    if clean is None:
        if folder in CLEAN_PFX and nm: clean=f"{CLEAN_PFX[folder]} {nm}"
        elif folder=='Click/Pop': clean={'clop':'Clop Pop','pop':'Bubble Pop'}[base_ns]
        elif folder=='Glitch' and re.match(r'glitch \d+',base_ns): clean=f"Glitch {int(base_ns.split()[1]):02d}"
        elif folder=='Glitch' and re.search('[\u0400-\u04ff]',base_ns): clean='Glitch Sound'
        elif base_ns=='Wasted': clean='GTA Wasted Sting'
    if re.search('[\u0400-\u04ff]',base_ns) and not clean: raise Exception(base)
    cat_=cat(sp['folder'])
    tags=list(dict.fromkeys(sp['tags']+['sfx']))[:8]
    notes=sp.get('notes')
    dur=x['duration_s']
    if a.get('onset_s',0)>0.8: notes=(notes+'; ' if notes else '')+f"starts with {a['onset_s']}s of silence"
    out.append(dict(
        id=x['id'],description=sp['desc']+f" ({dur:.1f}s).",moments=sp['moments'][:5],roles=sp['roles'][:3],tags=tags,
        quote=sp.get('quote'),mood=sp['mood'],energy=sp['energy'],content_rating=sp.get('rating','clean'),
        copyright_risk=sp.get('copyright','low'),placement='audio_only',key_mode='none',use_window=None,
        volume_db=vol,frequency=sp.get('frequency','common' if cat_=='sfx_ui' or sp['folder'] in(F_GLITCH,F_FOLEY,F_TOON) else 'rare'),notes=notes,
        category=cat_,folder=sp['folder'],clean_name=clean))
os.makedirs(ROOT+'tags',exist_ok=True)
json.dump(out,open(ROOT+'tags/incoming_sfxlib_a.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
ids=[x['id'] for x in batch]
assert [o['id'] for o in out]==ids and len(set(ids))==680
for o in out:
    assert o['folder'] in T['folders'],o
    assert all(m in T['moments'] for m in o['moments']),o
    assert all(r in T['roles'] for r in o['roles']),o
    assert o['placement'] in T['placement'] and o['key_mode'] in T['key_modes']
    assert o['content_rating'] in T['content_rating'] and o['copyright_risk'] in T['copyright_risk']
